1	// A constitutional signal must be distinguishable from prose ABOUT that signal.
2	// This used to also match the bare word "驳回" ("reject/return"), which is
3	// ordinary Chinese: 33 of the 57 regime files contain 驳回/诏书/圣旨 as plain
4	// historical vocabulary, while [VETO] is the only marker any regime actually
5	// teaches its agents to emit.
6	//
7	// The bare match was dormant only because office deliberation never reached this
8	// scanner — the old `-p` text output discarded it. The moment stream-json
9	// capture landed, a real Tang run was SIGKILLed mid-draft: the Secretariat was
10	// *describing* the Chancellery's power to amend and return documents
11	// ("直接在文书上批改驳回") and the engine read it as an act of veto.
12	//
13	// Bracketed markers only. A regime that wants a Chinese marker should be taught
14	// "[封驳]", which cannot occur by accident in prose.
15	const VETO_MARKERS = ["[VETO]", "[封驳]"];
16	
17	export function checkVeto(chunkText, context) {
18	  const text = String(chunkText ?? "");
19	  if (VETO_MARKERS.some((m) => text.includes(m))) {
20	    if (context.vetoImmunity) {
21	      console.error("\n[v6-Mechanism] Veto attempted but bypassed due to active Imperial Edict (vetoImmunity).");
22	      return false;
23	    }
24	    if (!context.vetoTriggered) {
25	      context.vetoTriggered = true;
26	      console.error("\n[v6-Mechanism] VETO DETECTED! Hard-aborting execution to simulate constitutional veto.");
27	      context.log.emit("veto_triggered", { reason: "Constitutional veto executed by auditing agent." });
28	      
29	      // Trigger the SIGKILL through the provided process
30	      if (context.ccProcess) {
31	        context.ccProcess.kill("SIGKILL");
32	      }
33	      return true; // Veto was triggered
34	    }
35	  }
36	  return false;
37	}
